mod biome;
mod export;
mod generation;
mod noise;
mod world;

use clap::{Parser, ValueEnum};
use export::{export_json, export_legend_png, export_noise_maps, export_png, export_svg};
use generation::{generate_world, gravity_modifier};
use rand::RngExt;
use std::error::Error;
use std::path::PathBuf;
use world::PlanetType;

/// Procedural planet map generator.
///
/// Every omitted option is chosen randomly; the chosen values are printed so
/// any world can be regenerated by passing them back explicitly.
#[derive(Parser)]
#[command(version, about)]
struct Args {
    /// Planet archetype [default: random]
    #[arg(long, value_enum)]
    planet: Option<PlanetType>,

    /// Waterline shift in [-1, 1]; positive means more ocean [default: random in -0.30..0.50]
    #[arg(long, allow_negative_numbers = true, value_parser = parse_in_range(-1.0, 1.0))]
    sea_level: Option<f32>,

    /// Share of mountain chains that become volcanic, in [0, 1] [default: random]
    #[arg(long, value_parser = parse_in_range(0.0, 1.0))]
    volcanic: Option<f32>,

    /// Equatorial circumference in km [default: random in 20000..80000]
    #[arg(long, value_parser = parse_in_range(1.0, f32::MAX))]
    circumference: Option<f32>,

    /// Noise seed [default: random]
    #[arg(long)]
    seed: Option<u32>,

    /// Map width in pixels
    #[arg(long, default_value_t = 1920, value_parser = clap::value_parser!(i32).range(2..=16384))]
    width: i32,

    /// Map height in pixels
    #[arg(long, default_value_t = 1080, value_parser = clap::value_parser!(i32).range(2..=16384))]
    height: i32,

    /// Directory that receives the generated worlds
    #[arg(long, default_value = "worlds")]
    out_dir: PathBuf,

    /// Skip the raw JSON export (several hundred MB at full resolution)
    #[arg(long)]
    no_json: bool,

    /// Skip the diagnostic noise maps
    #[arg(long)]
    no_noise_maps: bool,
}

/// Builds a clap value parser that accepts an `f32` within `[min, max]`.
fn parse_in_range(min: f32, max: f32) -> impl Fn(&str) -> Result<f32, String> + Clone {
    move |s| {
        let v: f32 = s.parse().map_err(|e| format!("{e}"))?;
        if (min..=max).contains(&v) {
            Ok(v)
        } else {
            Err(format!("must be between {min} and {max}"))
        }
    }
}

fn main() -> Result<(), Box<dyn Error>> {
    let args = Args::parse();
    let mut rng = rand::rng();

    let planet_type = args.planet.unwrap_or_else(|| {
        let all = PlanetType::value_variants();
        all[rng.random_range(0..all.len())]
    });
    let sea_level = args
        .sea_level
        .unwrap_or_else(|| rng.random_range(-0.30..0.50));
    let volcanic_intensity = args.volcanic.unwrap_or_else(|| rng.random_range(0.0..1.0));
    // Sub-Earth to ~2× Earth (Earth ≈ 40 075 km).
    let circumference_km = args
        .circumference
        .unwrap_or_else(|| rng.random_range(20_000.0..80_000.0));
    let seed = args.seed.unwrap_or_else(|| rng.random());

    println!(
        "Parameters → planet={planet_type} seed={seed} sea_level={sea_level:.2} \
         volcanic={volcanic_intensity:.2} circumference={circumference_km:.0} km \
         gravity≈{:.2}g",
        gravity_modifier(circumference_km)
    );

    let world = generate_world(
        args.width,
        args.height,
        seed,
        sea_level,
        volcanic_intensity,
        planet_type,
        circumference_km,
    );

    let dir = args.out_dir.join(format!("{planet_type}-{seed}"));
    let dir_str = |sub: &str| dir.join(sub).to_string_lossy().into_owned();
    std::fs::create_dir_all(&dir)?;

    export_png(&world, &dir_str("world.png"))?;
    export_svg(&world, &dir_str("world.svg"))?;
    export_legend_png(&world, &dir_str("legend.png"))?;
    if !args.no_json {
        std::fs::create_dir_all(dir.join("raw_data"))?;
        export_json(&world, &dir_str("raw_data/world.json"))?;
    }
    if !args.no_noise_maps {
        std::fs::create_dir_all(dir.join("noise_maps"))?;
        export_noise_maps(&world, &dir_str("noise_maps"))?;
    }

    println!("World generated → {}/", dir.display());
    // Exact values (the summary above is rounded) so the world can be regenerated.
    println!(
        "Reproduce with: --planet {planet_type} --seed {seed} --sea-level {sea_level} \
         --volcanic {volcanic_intensity} --circumference {circumference_km}"
    );
    Ok(())
}
